/**
 * Observe golden parity suite: pins packages/caelus/src/observe.ts
 * (sceneGeometry, verifyObservation, chronolocate, geolocate) against every
 * case in observe-golden.json generated by python/export_observe_golden.py.
 *
 * Both implementations run on identical embedded VSOP + full Moon data, so
 * structure and strings match exactly and floats match near machine precision.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { Engine } from "../src/chart.js";
import { loadNodeData } from "../src/node-loader.js";
import {
  sceneGeometry,
  verifyObservation,
  chronolocate,
  geolocate,
  type SceneGeometry,
  type SceneGeometryOptions,
  type ObservationClaim,
  type ObservationPlace,
  type ObservedConstraints,
  type ObservationTolerances,
  type ObservationVerification,
  type ObservationCheck,
  type ObservationDiagnostics,
  type ChronolocateResult,
  type GeolocateResult,
} from "../src/observe.js";

const here = dirname(fileURLToPath(import.meta.url));
const G = JSON.parse(readFileSync(join(here, "../../test/observe-golden.json"), "utf8"));
const eng = new Engine(loadNodeData(join(here, "../../data"), "embedded", "full"));

// -------------------------------------------------- snake_case <-> camelCase

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function toTolerances(raw: any): ObservationTolerances | undefined {
  if (!raw) return undefined;
  return {
    shadowBearingDeg: raw.shadow_bearing_deg,
    shadowLengthRatio: raw.shadow_length_ratio,
    shadowLengthRatioRel: raw.shadow_length_ratio_rel,
    shadowLengthRatioAbs: raw.shadow_length_ratio_abs,
    sunAzimuthDeg: raw.sun_azimuth_deg,
    sunAltitudeDeg: raw.sun_altitude_deg,
    moonAzimuthDeg: raw.moon_azimuth_deg,
    moonAltitudeDeg: raw.moon_altitude_deg,
    moonIllum: raw.moon_illum,
    moonBrightLimbDeg: raw.moon_bright_limb_deg,
    shadowSweepDeg: raw.shadow_sweep_deg,
  };
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function toObserved(raw: any): ObservedConstraints | null {
  if (raw === null || raw === undefined) return null;
  return {
    shadowBearingDeg: raw.shadow_bearing_deg,
    shadowLengthRatio: raw.shadow_length_ratio,
    sunAzimuthDeg: raw.sun_azimuth_deg,
    sunAltitudeDeg: raw.sun_altitude_deg,
    twilight: raw.twilight,
    sunVisible: raw.sun_visible,
    moonVisible: raw.moon_visible,
    moonAzimuthDeg: raw.moon_azimuth_deg,
    moonAltitudeDeg: raw.moon_altitude_deg,
    moonIllum: raw.moon_illum,
    moonWaxing: raw.moon_waxing,
    moonBrightLimbDeg: raw.moon_bright_limb_deg,
    bodiesVisible: raw.bodies_visible,
    shadowSweep: raw.shadow_sweep
      ? {
        dtMinutes: raw.shadow_sweep.dt_minutes,
        deltaBearingDeg: raw.shadow_sweep.delta_bearing_deg,
        toleranceDeg: raw.shadow_sweep.tolerance_deg,
      }
      : undefined,
    tolerances: toTolerances(raw.tolerances),
  };
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function toSceneOpts(raw: any): SceneGeometryOptions {
  if (!raw) return {};
  return {
    elevationM: raw.elevation_m,
    slopeDeg: raw.slope_deg,
    slopeAzimuthDeg: raw.slope_azimuth_deg,
    bortle: raw.bortle ?? undefined,
    cameraAimAzDeg: raw.camera_aim_az_deg ?? undefined,
    cameraAimAltDeg: raw.camera_aim_alt_deg,
    prevJdUt: raw.prev_jd_ut ?? undefined,
    deadlineJdUt: raw.deadline_jd_ut ?? undefined,
  };
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function toPlace(raw: any): ObservationPlace {
  return {
    lat: raw.lat,
    lonEast: raw.lon_east,
    elevationM: raw.elevation_m,
    slopeDeg: raw.slope_deg,
    slopeAzimuthDeg: raw.slope_azimuth_deg,
    bortle: raw.bortle ?? undefined,
  };
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function toClaim(raw: any): ObservationClaim {
  return {
    jdUt: raw.jd_ut,
    lat: raw.lat,
    lonEast: raw.lon_east,
    elevationM: raw.elevation_m,
    slopeDeg: raw.slope_deg,
    slopeAzimuthDeg: raw.slope_azimuth_deg,
    timeToleranceMin: raw.time_tolerance_min,
    placeToleranceDeg: raw.place_tolerance_deg,
    bortle: raw.bortle ?? undefined,
    cameraAimAzDeg: raw.camera_aim_az_deg ?? undefined,
    cameraAimAltDeg: raw.camera_aim_alt_deg,
    prevJdUt: raw.prev_jd_ut ?? undefined,
    deadlineJdUt: raw.deadline_jd_ut ?? undefined,
  };
}

const CHECK_FIELD_TO_SNAKE: Record<string, string> = {
  shadowBearingDeg: "shadow_bearing_deg",
  shadowLengthRatio: "shadow_length_ratio",
  sunAzimuthDeg: "sun_azimuth_deg",
  sunAltitudeDeg: "sun_altitude_deg",
  twilight: "twilight",
  sunVisible: "sun_visible",
  moonVisible: "moon_visible",
  moonAzimuthDeg: "moon_azimuth_deg",
  moonAltitudeDeg: "moon_altitude_deg",
  moonIllum: "moon_illum",
  moonWaxing: "moon_waxing",
  moonBrightLimbDeg: "moon_bright_limb_deg",
  shadowSweep: "shadow_sweep",
};

function fieldToSnake(f: string): string {
  if (f.startsWith("bodyVisible:")) return `body_visible:${f.slice("bodyVisible:".length)}`;
  return CHECK_FIELD_TO_SNAKE[f] ?? f;
}

function mapScene(s: SceneGeometry): unknown {
  return {
    jd_ut: s.jdUt,
    lat: s.lat,
    lon_east: s.lonEast,
    elevation_m: s.elevationM,
    sun: {
      azimuth_deg: s.sun.azimuthDeg,
      compass16: s.sun.compass16,
      altitude_true_deg: s.sun.altitudeTrueDeg,
      altitude_apparent_deg: s.sun.altitudeApparentDeg,
      airmass: s.sun.airmass,
      extinction_mag: s.sun.extinctionMag,
      twilight_stage: s.sun.twilightStage,
      is_day: s.sun.isDay,
      trend: s.sun.trend,
      rate_alt_deg_per_min: s.sun.rateAltDegPerMin,
      rate_az_deg_per_min: s.sun.rateAzDegPerMin,
      angular_diameter_deg: s.sun.angularDiameterDeg,
    },
    shadow: {
      cast: s.shadow.cast,
      self_shadowed: s.shadow.selfShadowed,
      bearing_deg: s.shadow.bearingDeg,
      compass16: s.shadow.compass16,
      length_ratio: s.shadow.lengthRatio,
      horizontal_length_ratio: s.shadow.horizontalLengthRatio,
      rate_bearing_deg_per_min: s.shadow.rateBearingDegPerMin,
      rate_length_ratio_per_min: s.shadow.rateLengthRatioPerMin,
      penumbra_deg: s.shadow.penumbraDeg,
      slope_deg: s.shadow.slopeDeg,
      slope_azimuth_deg: s.shadow.slopeAzimuthDeg,
    },
    lighting: s.lighting === null
      ? null
      : {
        camera_aim_az_deg: s.lighting.cameraAimAzDeg,
        camera_aim_alt_deg: s.lighting.cameraAimAltDeg,
        sun_relative_az_deg: s.lighting.sunRelativeAzDeg,
        shadow_screen_az_deg: s.lighting.shadowScreenAzDeg,
        sun_camera_angle_deg: s.lighting.sunCameraAngleDeg,
        glare_risk: s.lighting.glareRisk,
      },
    moon: {
      visible: s.moon.visible,
      azimuth_deg: s.moon.azimuthDeg,
      compass16: s.moon.compass16,
      altitude_true_deg: s.moon.altitudeTrueDeg,
      altitude_apparent_deg: s.moon.altitudeApparentDeg,
      illum: s.moon.illum,
      phase_name: s.moon.phaseName,
      waxing: s.moon.waxing,
      elongation_deg: s.moon.elongationDeg,
      magnitude: s.moon.magnitude,
      bright_limb_zenith_deg: s.moon.brightLimbZenithDeg,
      bright_limb_clock: s.moon.brightLimbClock,
      shadow_cast: s.moon.shadowCast,
      shadow_bearing_deg: s.moon.shadowBearingDeg,
      shadow_length_ratio: s.moon.shadowLengthRatio,
    },
    visible_planets: s.visiblePlanets.map((p) => ({
      id: p.id,
      azimuth_deg: p.azimuthDeg,
      compass16: p.compass16,
      altitude_apparent_deg: p.altitudeApparentDeg,
      magnitude: p.magnitude,
      naked_eye: p.nakedEye,
    })),
    diurnal: {
      sunrise_jd: s.diurnal.sunriseJd,
      solar_noon_jd: s.diurnal.solarNoonJd,
      sunset_jd: s.diurnal.sunsetJd,
      minutes_to_next_twilight: s.diurnal.minutesToNextTwilight,
      next_transition_kind: s.diurnal.nextTransitionKind,
      planetary_hour: s.diurnal.planetaryHour === null
        ? null
        : {
          ruler: s.diurnal.planetaryHour.ruler,
          kind: s.diurnal.planetaryHour.kind,
          hour: s.diurnal.planetaryHour.hour,
          day_ruler: s.diurnal.planetaryHour.dayRuler,
          start: s.diurnal.planetaryHour.start,
          end: s.diurnal.planetaryHour.end,
        },
    },
    chronosense: {
      moon_lon_deg: s.chronosense.moonLonDeg,
      asc_deg: s.chronosense.ascDeg,
      night_crossed: s.chronosense.nightCrossed,
      deadline: s.chronosense.deadline === null
        ? null
        : {
          minutes_remaining: s.chronosense.deadline.minutesRemaining,
          phase: s.chronosense.deadline.phase,
        },
      line: s.chronosense.line,
    },
  };
}

function mapCheck(c: ObservationCheck): unknown {
  return {
    field: fieldToSnake(c.field),
    status: c.status,
    observed: c.observed,
    expected: c.expected,
    residual: c.residual,
    tolerance: c.tolerance,
    normalized_residual: c.normalizedResidual,
    note: c.note,
  };
}

function mapDiagnostics(d: ObservationDiagnostics | null): unknown {
  if (d === null) return null;
  return {
    time_shift: {
      jd_ut: d.timeShift.jdUt,
      offset_minutes: d.timeShift.offsetMinutes,
      nearest_whole_hour_offset: d.timeShift.nearestWholeHourOffset,
      fit_score: d.timeShift.fitScore,
      verdict: d.timeShift.verdict,
    },
    hemisphere_flip: {
      lat: d.hemisphereFlip.lat,
      lon_east: d.hemisphereFlip.lonEast,
      fit_score: d.hemisphereFlip.fitScore,
      verdict: d.hemisphereFlip.verdict,
    },
    date_shift: d.dateShift === null
      ? null
      : {
        jd_ut: d.dateShift.jdUt,
        offset_days: d.dateShift.offsetDays,
        fit_score: d.dateShift.fitScore,
        verdict: d.dateShift.verdict,
      },
    summary: d.summary,
  };
}

function mapVerify(v: ObservationVerification): unknown {
  return {
    verdict: v.verdict,
    consistency_score: v.consistencyScore,
    checks: v.checks.map(mapCheck),
    scene: mapScene(v.scene),
    diagnostics: mapDiagnostics(v.diagnostics),
  };
}

function mapChrono(r: ChronolocateResult): unknown {
  return {
    place: {
      lat: r.place.lat,
      lon_east: r.place.lonEast,
      elevation_m: r.place.elevationM,
      slope_deg: r.place.slopeDeg,
      slope_azimuth_deg: r.place.slopeAzimuthDeg,
    },
    jd_start: r.jdStart,
    jd_end: r.jdEnd,
    days_scanned: r.daysScanned,
    days_pruned: r.daysPruned,
    windows: r.windows.map((w) => ({
      jd_start: w.jdStart,
      jd_end: w.jdEnd,
      best_jd: w.bestJd,
      duration_minutes: w.durationMinutes,
      fit_score: w.fitScore,
      max_normalized_residual: w.maxNormalizedResidual,
    })),
    truncated: r.truncated,
  };
}

function mapGeo(r: GeolocateResult): unknown {
  return {
    jd_ut: r.jdUt,
    method: r.method,
    subsolar: r.subsolar,
    sublunar: r.sublunar,
    candidates: r.candidates.map((c) => ({
      lat: c.lat,
      lon: c.lon,
      fit_score: c.fitScore,
      max_normalized_residual: c.maxNormalizedResidual,
      radius_km: c.radiusKm,
      lat_range: c.latRange,
      lon_range: c.lonRange,
      region_kind: c.regionKind,
    })),
  };
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function runCase(c: any): unknown {
  const s = c.spec;
  switch (c.type) {
    case "scene":
      return mapScene(sceneGeometry(eng, s.jd_ut, s.lat, s.lon_east, toSceneOpts(s.options)));
    case "verify":
      return mapVerify(verifyObservation(eng, toClaim(s.claim), toObserved(s.observed)));
    case "chronolocate":
      return mapChrono(chronolocate(
        eng,
        toPlace(s.place),
        toObserved(s.observed)!,
        s.jd_start,
        s.jd_end,
        {
          stepMinutes: s.options?.step_minutes,
          maxWindows: s.options?.max_windows,
        },
      ));
    case "geolocate":
      return mapGeo(geolocate(
        eng,
        s.jd_ut,
        toObserved(s.observed)!,
        {
          latMin: s.options?.lat_min,
          latMax: s.options?.lat_max,
          lonMin: s.options?.lon_min,
          lonMax: s.options?.lon_max,
          gridStepDeg: s.options?.grid_step_deg,
          maxCandidates: s.options?.max_candidates,
          elevationM: s.options?.elevation_m,
          slopeDeg: s.options?.slope_deg,
          slopeAzimuthDeg: s.options?.slope_azimuth_deg,
          bortle: s.options?.bortle ?? undefined,
        },
      ));
    default:
      throw new Error(`unknown golden case type ${c.type}`);
  }
}

let checks = 0;
let failures = 0;
let worst = 0;
let worstPath = "";
const TOL = 1e-6;

const CYCLIC_360_KEYS = new Set([
  "azimuth_deg", "bearing_deg", "bright_limb_zenith_deg",
  "shadow_bearing_deg", "moon_lon_deg", "asc_deg",
]);

function cyclicDiff360(a: number, b: number): number {
  const r = (((a - b) + 180.0) % 360.0 + 360.0) % 360.0 - 180.0;
  return Math.abs(r);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function leaf(id: string, got: any, want: any, key?: string): void {
  checks++;
  if (typeof want === "number") {
    const d = (key && CYCLIC_360_KEYS.has(key))
      ? cyclicDiff360(got, want)
      : Math.abs(got - want);
    if (d > worst) {
      worst = d;
      worstPath = id;
    }
    if (typeof got !== "number" || !Number.isFinite(got) || d > TOL) {
      failures++;
      console.error(`FAIL ${id}: ${got} vs ${want} (diff ${d})`);
    }
  } else if (got !== want) {
    failures++;
    console.error(`FAIL ${id}: ${JSON.stringify(got)} vs ${JSON.stringify(want)}`);
  }
}

// At exact zenith (alt === 90 deg, e.g. subsolar point), atan2(0, 0) azimuth is
// a coordinate singularity where a 1-ULP hour-angle difference rotates azimuth
// arbitrarily; shadow bearing is explicitly marked "indeterminate" there.
const ZENITH_SINGULAR_SUFFIXES = [
  ".scene.sun.azimuth_deg",
  ".scene.sun.compass16",
  ".scene.shadow.bearing_deg",
  ".scene.shadow.compass16",
  ".checks[0].expected",
];

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function deepCmp(id: string, got: any, want: any, key?: string, isZenithCase = false): void {
  if (isZenithCase && ZENITH_SINGULAR_SUFFIXES.some((s) => id.endsWith(s))) {
    checks++;
    if (typeof want === "number" && (typeof got !== "number" || !Number.isFinite(got) || got < 0 || got >= 360)) {
      failures++;
      console.error(`FAIL ${id}: singular zenith angle must be finite in [0, 360), got ${got}`);
    } else if (typeof want === "string" && (typeof got !== "string" || got.length === 0)) {
      failures++;
      console.error(`FAIL ${id}: singular zenith compass must be non-empty string, got ${got}`);
    }
    return;
  }
  if (isZenithCase && id.endsWith(".scene.chronosense.line")) {
    // Strip the singular Sun/shadow compass tokens at exact 90.0 deg zenith.
    const normLine = (s: string) => s
      .replace(/Sun 90\.0deg [A-Z]+ culminating/, "Sun 90.0deg * culminating")
      .replace(/shd 0\.00x [A-Z]+/, "shd 0.00x *");
    leaf(id, normLine(String(got)), normLine(String(want)));
    return;
  }
  if (Array.isArray(want)) {
    if (!Array.isArray(got) || got.length !== want.length) {
      checks++;
      failures++;
      console.error(`FAIL ${id}: array length ${got?.length} vs ${want.length}`);
      return;
    }
    for (let i = 0; i < want.length; i++) deepCmp(`${id}[${i}]`, got[i], want[i], undefined, isZenithCase);
  } else if (want !== null && typeof want === "object") {
    if (got === null || typeof got !== "object") {
      checks++;
      failures++;
      console.error(`FAIL ${id}: got ${JSON.stringify(got)}, want object`);
      return;
    }
    for (const k of Object.keys(want)) deepCmp(`${id}.${k}`, got[k], want[k], k, isZenithCase);
  } else {
    leaf(id, got, want, key);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
for (const c of G.cases as any[]) {
  const isZenith = c.id === "verify-lahaina-zenith";
  deepCmp(c.id, runCase(c), c.result, undefined, isZenith);
}

console.log(`observe-golden: ${G.cases.length} cases, ${checks} checks, ${failures} failures`);
console.log(`worst numeric diff: ${worst.toExponential(2)} (${worstPath})`);
process.exit(failures === 0 ? 0 : 1);
